def components(g,val):
    H,W=len(g),len(g[0]); seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==val and (ny,nx) not in seen: st.append((ny,nx))
                comps.append(comp)
    return comps
